g=[[4]*16 for _ in range(19)]
pts=[(2,2,1),(4,4,6),(4,14,1),(6,6,6),(7,14,6),(10,10,1),(15,2,6),(17,9,1)]
for r,c,v in pts:g[r][c]=v
# diagonal collinear connections among same-color points
for i,(r,c,v) in enumerate(pts):
 for R,C,w in pts[i+1:]:
  if v==w and abs(R-r)==abs(C-c):
   dr=1 if R>r else -1; dc=1 if C>c else -1
   for k in range(abs(R-r)+1): g[r+k*dr][c+k*dc]=v
print(g)

R,C=19,16
g=[[4]*C for _ in range(R)]
pts=[(2,2,1),(4,4,6),(4,14,1),(6,6,6),(7,14,6),(10,10,1),(15,2,6),(17,9,1)]
for r,c,v in pts:g[r][c]=v
# 1 markers on same down-right diagonal are joined; 6 markers produce their down-right diagonal across the canvas
for r,c,v in pts:
 if v==6:
  # extend both directions along slope +1
  for rr in range(R):
   cc=c+(rr-r)
   if 0<=cc<C:g[rr][cc]=6
# join aligned 1 points along diagonal
ones=[(r,c) for r,c,v in pts if v==1]
for i,(r,c) in enumerate(ones):
 for rr,cc in ones[i+1:]:
  if rr-r==cc-c:
   for k in range(abs(rr-r)+1):g[r+k][c+k]=1
print(g)

